ValidationRule.errorConditionFormula:
AND(
    OR(RecordType.DeveloperName = "NewOperationalTest", RecordType.DeveloperName = "OldNewOperationalTest"),
    OR(
        AND(
            ISPICKVAL(StageName__c, "フェーズ3 引合い"),
            OR(
                NOT(INCLUDES(CompletionBasis__c, "3-1:これまでの仮説検討に沿い、お客様に適当な商品を選択し、提案した。")),
                NOT(INCLUDES(CompletionBasis__c, "3-2:お客様の現場を訪問した。")),
                NOT(INCLUDES(CompletionBasis__c, "3-3:概算見積もり、費用対効果を提示するアポイントが取れた。"))
            )
        )
    )
)
